import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  img: { fill: '#e8f5e9', stroke: '#4caf50' },
  patch: { fill: '#e3f2fd', stroke: '#1976d2' },
  pos: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  text: { fill: '#fff3e0', stroke: '#e65100' },
  tok: { fill: '#fce4ec', stroke: '#c62828' },
  enc: { fill: '#ede7f6', stroke: '#4527a0' },
  attn: { fill: '#fff8e1', stroke: '#ff8f00' },
  ffn: { fill: '#e8eaf6', stroke: '#283593' },
  norm: { fill: '#e0f2f1', stroke: '#00897b' },
  proj: { fill: '#e0f2f1', stroke: '#00897b' },
  sim: { fill: '#fff9c4', stroke: '#f57f17' },
  loss: { fill: '#ffebee', stroke: '#b71c1c' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  textCol: 'var(--text)' as string,
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const BRANCH_W = 440;
const CENTER_W = 640;
const MAT_H = 80;
const SEQ_W = 180;
const WEIGHT_W = 110;
const WEIGHT_H = 70;
const BOX_TO_ROW = 90;
const ROW_GAP = 64;
const STEP_GAP = 76;
const IMG_CX = 240;
const TXT_CX = 720;

function lbl(g: Gsel, x: number, y: number, t: string, opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}): void {
  drawLabel(g as Sel, x, y, t, opts);
}
function arrowV(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void { drawArrow(g as Sel, x, y1, x, y2, { color }); }
function startGroup(g: Gsel, cls: string, step: number): Gsel { return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step)); }

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string, fill: string, stroke: string, width = BRANCH_W): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H).attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 24).attr('cy', y + BOX_H / 2).attr('r', 14).attr('fill', stroke);
  lbl(g, cx - w / 2 + 24, y + BOX_H / 2 + 1, String(sn), { size: 12, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 48, y + BOX_H / 2 - 6, title, { size: 13, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 48, y + BOX_H / 2 + 10, formula, { size: 9, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function drawShapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 28, 180);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 14).attr('width', w).attr('height', 28).attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy, text, { size: 8.5, color, font: 'monospace' });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const bw = Math.max(90, text.length * 7.5 + 20);
  g.append('rect').attr('x', cx - bw / 2).attr('y', cy - 17).attr('width', bw).attr('height', 34).attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '600', color: stroke });
}

function drawSeqMat(g: Gsel, cx: number, cy: number, label: string, sub: string, fill: string, stroke: string, w = SEQ_W, h = MAT_H): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 7, rows: 5, dimTop: 'S', dimRight: 'D' });
}

function drawWeightMat(g: Gsel, cx: number, cy: number, label: string, sub: string, fill = COLORS.weight.fill, stroke = COLORS.weight.stroke, w = WEIGHT_W, h = WEIGHT_H): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 5 });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 18).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function drawParamSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160; const h = 34;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h).attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => { lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' }); });
  return y + h;
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string, sg: string, c: string, fl: string, cl?: string[]): StepInfo {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex, code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function drawImageGrid(g: Gsel, cx: number, cy: number, gridN: number, color: string, size = 180): void {
  const gg = g.append('g').attr('transform', `translate(${cx - size / 2}, ${cy - size / 2})`);
  gg.append('rect').attr('width', size).attr('height', size).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  const cw = size / gridN; const ch = size / gridN;
  let seed = 42;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  for (let r = 0; r < gridN; r++) for (let c = 0; c < gridN; c++) {
    gg.append('rect').attr('x', c * cw + 0.5).attr('y', r * ch + 0.5).attr('width', cw - 1).attr('height', ch - 1).attr('rx', 1).attr('fill', color).attr('opacity', 0.15 + lcg() * 0.55);
  }
  if (gridN <= 14) for (let i = 1; i < gridN; i++) {
    gg.append('line').attr('x1', i * cw).attr('y1', 0).attr('x2', i * cw).attr('y2', size).attr('stroke', '#fff').attr('stroke-width', 0.3).attr('opacity', 0.5);
    gg.append('line').attr('x1', 0).attr('y1', i * ch).attr('x2', size).attr('y2', i * ch).attr('stroke', '#fff').attr('stroke-width', 0.3).attr('opacity', 0.5);
  }
}

function drawTokenStrip(g: Gsel, cx: number, cy: number, nShow: number, color: string, w = 300, h = 56): void {
  const gg = g.append('g').attr('transform', `translate(${cx - w / 2}, ${cy - h / 2})`);
  gg.append('rect').attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  const cw = w / (nShow + 1);
  for (let i = 0; i < nShow; i++) {
    const op = 0.15 + (i / nShow) * 0.5;
    gg.append('rect').attr('x', i * cw + 2).attr('y', 4).attr('width', cw - 4).attr('height', h - 8).attr('rx', 2).attr('fill', color).attr('opacity', op);
  }
}

function drawPosEncoding(g: Gsel, cx: number, cy: number, n: number, color: string, w = 180, h = 60): void {
  const gg = g.append('g').attr('transform', `translate(${cx - w / 2}, ${cy - h / 2})`);
  gg.append('rect').attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 0.8);
  const nCols = Math.min(n, 14); const nRows = 5;
  const cw = w / nCols; const ch = h / nRows;
  for (let r = 0; r < nRows; r++) for (let c = 0; c < nCols; c++) {
    const v = Math.sin(c * 0.5 + r * 1.3) * 0.4 + 0.5;
    gg.append('rect').attr('x', c * cw).attr('y', r * ch).attr('width', cw - 0.5).attr('height', ch - 0.5).attr('rx', 1).attr('fill', color).attr('opacity', Math.max(0.05, v * 0.6));
  }
}

function renderClipPipeline(g: Gsel, startY: number, dModel: number, nPatches: number, seqLen: number): { steps: StepInfo[]; y: number } {
  const steps: StepInfo[] = [];
  let y = startY;
  const patchSize = 16;
  const gridN = Math.round(Math.sqrt(nPatches));
  const patchDim = patchSize * patchSize * 3;
  const dProj = dModel;

  // ═══════════════════════════════════════════════════════════════════════
  // IMAGE BRANCH (left)
  // ═══════════════════════════════════════════════════════════════════════
  let imgStepId = 1;
  let iy = y;

  // ── Step 1: Input Image ──
  {
    const gs = startGroup(g, 'step-img', imgStepId);
    const h = stepHeader(gs, IMG_CX, iy, imgStepId, 'Input Image', `[3, ${patchSize * gridN}, ${patchSize * gridN}]`, COLORS.img.fill, COLORS.img.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.img.stroke);
    const gridCY = h + BOX_TO_ROW + 90;
    drawImageGrid(gs, IMG_CX, gridCY, Math.min(gridN, 14), COLORS.img.stroke, 180);
    lbl(gs, IMG_CX, gridCY + 90 + 18, `${patchSize * gridN}×${patchSize * gridN} RGB`, { size: 9, color: COLORS.muted });
    steps.push(makeStep(imgStepId, 'Image', 'Input Image', `[3, ${patchSize * gridN}, ${patchSize * gridN}]`, `Input RGB image of size ${patchSize * gridN}×${patchSize * gridN}.`, 'step-img', COLORS.img.stroke, COLORS.img.fill));
    imgStepId++; iy = gridCY + 90 + STEP_GAP;
  }

  // ── Step 2: Patchify ──
  {
    const gs = startGroup(g, 'step-patch', imgStepId);
    const h = stepHeader(gs, IMG_CX, iy, imgStepId, 'Patchify', `→ [${nPatches}, ${patchDim}]`, COLORS.patch.fill, COLORS.patch.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.patch.stroke);
    const rowY = h + BOX_TO_ROW + 30;
    drawTokenStrip(gs, IMG_CX, rowY, Math.min(nPatches, 10), COLORS.patch.stroke, 300, 52);
    lbl(gs, IMG_CX, rowY - 36, `${nPatches} patches`, { size: 9, color: COLORS.muted });
    lbl(gs, IMG_CX, rowY + 36, `each: ${patchSize}×${patchSize}×3 = ${patchDim}d`, { size: 8.5, color: COLORS.muted });
    const outY = rowY + 26 + ROW_GAP + MAT_H / 2;
    arrowV(gs, IMG_CX, rowY + 26 + 18, outY - MAT_H / 2, COLORS.patch.stroke);
    drawSeqMat(gs, IMG_CX, outY, 'patches', `[${nPatches}, ${patchDim}]`, COLORS.patch.fill, COLORS.patch.stroke);
    drawShapeEq(gs, IMG_CX, outY + MAT_H / 2 + 24, `reshape → [${nPatches}, ${patchDim}]`, COLORS.patch.stroke);
    steps.push(makeStep(imgStepId, 'Patchify', 'Patchify', `reshape → [${nPatches}, ${patchDim}]`, 'Split image into patches and flatten.', 'step-patch', COLORS.patch.stroke, COLORS.patch.fill));
    imgStepId++; iy = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 3: Linear Projection ──
  {
    const gs = startGroup(g, 'step-proj', imgStepId);
    const h = stepHeader(gs, IMG_CX, iy, imgStepId, 'Linear Projection', `patches · W_p + b`, COLORS.patch.fill, COLORS.patch.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.patch.stroke);
    const rowY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, IMG_CX - 80, rowY, 'patches', `[${nPatches}, ${patchDim}]`, COLORS.patch.fill, COLORS.patch.stroke, 150, MAT_H);
    opCircle(gs, IMG_CX + 30, rowY, '×', COLORS.patch.stroke);
    drawArrow(gs as Sel, IMG_CX - 80 + 75 + 4, rowY, IMG_CX + 30 - 20, rowY, { color: COLORS.patch.stroke });
    drawWeightMat(gs, IMG_CX + 130, rowY, 'W_p', `[${patchDim}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 64);
    drawArrow(gs as Sel, IMG_CX + 30 + 20, rowY, IMG_CX + 130 - 50 - 4, rowY, { color: COLORS.patch.stroke });
    lbl(gs, IMG_CX + 130, rowY + 32 + 14, '+ b_p', { size: 8, color: COLORS.muted });
    const outY = rowY + MAT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowV(gs, IMG_CX + 50, rowY + MAT_H / 2, outY - MAT_H / 2, COLORS.patch.stroke);
    drawSeqMat(gs, IMG_CX, outY, 'img_emb', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke);
    drawShapeEq(gs, IMG_CX, outY + MAT_H / 2 + 24, `patches · W_p + b → [${nPatches}, ${dModel}]`, COLORS.patch.stroke);
    steps.push(makeStep(imgStepId, 'Project', 'Linear Projection', `patches · W_p + b`, 'Project patches to d_model.', 'step-proj', COLORS.patch.stroke, COLORS.patch.fill));
    imgStepId++; iy = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 4: Add Position Embedding ──
  {
    const gs = startGroup(g, 'step-ipos', imgStepId);
    const h = stepHeader(gs, IMG_CX, iy, imgStepId, 'Add Position Embedding', `x + PE`, COLORS.pos.fill, COLORS.pos.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.pos.stroke);
    const rowY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, IMG_CX - 80, rowY, 'img_emb', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke, 150, MAT_H);
    opCircle(gs, IMG_CX + 30, rowY, '+', COLORS.pos.stroke);
    drawArrow(gs as Sel, IMG_CX - 80 + 75 + 4, rowY, IMG_CX + 30 - 20, rowY, { color: COLORS.pos.stroke });
    drawPosEncoding(gs, IMG_CX + 140, rowY, nPatches, COLORS.pos.stroke, 130, 56);
    lbl(gs, IMG_CX + 140, rowY - 28 - 10, 'learned PE', { size: 8, color: COLORS.muted });
    drawArrow(gs as Sel, IMG_CX + 140 - 65 - 4, rowY, IMG_CX + 30 + 20, rowY, { color: COLORS.pos.stroke });
    const outY = rowY + MAT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowV(gs, IMG_CX + 30, rowY + MAT_H / 2, outY - MAT_H / 2, COLORS.pos.stroke);
    drawSeqMat(gs, IMG_CX, outY, 'x_embed', `[${nPatches}, ${dModel}]`, COLORS.pos.fill, COLORS.pos.stroke);
    drawShapeEq(gs, IMG_CX, outY + MAT_H / 2 + 24, `img_emb + PE → [${nPatches}, ${dModel}]`, COLORS.pos.stroke);
    steps.push(makeStep(imgStepId, 'PosEnc', 'Add Position Embedding', `x + PE`, 'Add learned positional embeddings.', 'step-ipos', COLORS.pos.stroke, COLORS.pos.fill));
    imgStepId++; iy = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 5: ViT Self-Attention ──
  {
    const gs = startGroup(g, 'step-vattn', imgStepId);
    const h = stepHeader(gs, IMG_CX, iy, imgStepId, 'ViT Self-Attention', `Attn(LN(x))`, COLORS.attn.fill, COLORS.attn.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.attn.stroke);
    const inY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, IMG_CX, inY, 'x_embed', `[${nPatches}, ${dModel}]`, COLORS.pos.fill, COLORS.pos.stroke);
    const lnY = inY + MAT_H / 2 + ROW_GAP;
    drawBadge(gs, IMG_CX, lnY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    arrowV(gs, IMG_CX, inY + MAT_H / 2, lnY - 17, COLORS.attn.stroke);
    const qkvY = lnY + 17 + ROW_GAP + 32;
    const qkvGap = 120;
    lbl(gs, IMG_CX - qkvGap, qkvY - 50, 'Q', { size: 9, weight: '600', color: COLORS.attn.stroke });
    lbl(gs, IMG_CX, qkvY - 50, 'K', { size: 9, weight: '600', color: COLORS.attn.stroke });
    lbl(gs, IMG_CX + qkvGap, qkvY - 50, 'V', { size: 9, weight: '600', color: COLORS.attn.stroke });
    drawWeightMat(gs, IMG_CX - qkvGap, qkvY, 'W_q', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 64);
    drawWeightMat(gs, IMG_CX, qkvY, 'W_k', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 64);
    drawWeightMat(gs, IMG_CX + qkvGap, qkvY, 'W_v', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 64);
    drawArrow(gs as Sel, IMG_CX, lnY + 17, IMG_CX - qkvGap, qkvY - 32 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, IMG_CX, lnY + 17, IMG_CX, qkvY - 32 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, IMG_CX, lnY + 17, IMG_CX + qkvGap, qkvY - 32 - 4, { color: COLORS.attn.stroke });
    const scoreY = qkvY + 32 + ROW_GAP;
    const scoreBoxW = 180; const scoreBoxH = 38;
    gs.append('rect').attr('x', IMG_CX - 60 - scoreBoxW / 2).attr('y', scoreY - scoreBoxH / 2).attr('width', scoreBoxW).attr('height', scoreBoxH).attr('rx', 6).attr('fill', '#fff').attr('stroke', COLORS.attn.stroke).attr('stroke-width', 1);
    lbl(gs, IMG_CX - 60, scoreY, `Q·K^T/√d`, { size: 9, weight: '600', color: COLORS.attn.stroke, font: 'monospace' });
    drawBadge(gs, IMG_CX + 80, scoreY, 'Softmax', COLORS.attn.fill, COLORS.attn.stroke);
    drawArrow(gs as Sel, IMG_CX - 60 + scoreBoxW / 2 + 4, scoreY, IMG_CX + 80 - 50, scoreY, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, IMG_CX - qkvGap, qkvY + 32, IMG_CX - 60 - 30, scoreY - scoreBoxH / 2 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, IMG_CX, qkvY + 32, IMG_CX - 60 + 30, scoreY - scoreBoxH / 2 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, IMG_CX + qkvGap, qkvY + 32, IMG_CX + 80, scoreY + scoreBoxH / 2 + 4, { color: COLORS.attn.stroke });
    const outY = scoreY + scoreBoxH / 2 + ROW_GAP + 30;
    drawWeightMat(gs, IMG_CX, outY, 'W_o', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 60);
    lbl(gs, IMG_CX, outY - 32 - 14, 'attn_weights · V', { size: 8, color: COLORS.muted });
    arrowV(gs, IMG_CX + 80, scoreY + scoreBoxH / 2 + 4, outY - 30, COLORS.attn.stroke);
    const attnOutY = outY + 30 + ROW_GAP + MAT_H / 2;
    arrowV(gs, IMG_CX, outY + 30, attnOutY - MAT_H / 2, COLORS.attn.stroke);
    drawSeqMat(gs, IMG_CX, attnOutY, 'attn_out', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke);
    drawShapeEq(gs, IMG_CX, attnOutY + MAT_H / 2 + 24, `softmax(Q·K^T/√d)·V·W_o → [${nPatches}, ${dModel}]`, COLORS.attn.stroke);
    steps.push(makeStep(imgStepId, 'Attn', 'ViT Self-Attention', `Attn(LN(x))`, 'Multi-head self-attention with Q/K/V projections.', 'step-vattn', COLORS.attn.stroke, COLORS.attn.fill));
    imgStepId++; iy = attnOutY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 6: ViT FFN ──
  {
    const gs = startGroup(g, 'step-vffn', imgStepId);
    const h = stepHeader(gs, IMG_CX, iy, imgStepId, 'ViT Feed-Forward', `FFN(LN(x)) + residual`, COLORS.ffn.fill, COLORS.ffn.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.ffn.stroke);
    const inY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, IMG_CX, inY, 'h_attn', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke);
    const lnY = inY + MAT_H / 2 + ROW_GAP;
    drawBadge(gs, IMG_CX, lnY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    arrowV(gs, IMG_CX, inY + MAT_H / 2, lnY - 17, COLORS.ffn.stroke);
    const dFf = 4 * dModel;
    const wUpY = lnY + 17 + ROW_GAP + WEIGHT_H / 2;
    drawWeightMat(gs, IMG_CX, wUpY, 'W_up', `[${dModel}, ${dFf}]`, COLORS.weight.fill, COLORS.weight.stroke, 120, WEIGHT_H);
    arrowV(gs, IMG_CX, lnY + 17, wUpY - WEIGHT_H / 2, COLORS.ffn.stroke);
    lbl(gs, IMG_CX + 80, wUpY - 10, 'up-project', { size: 8, color: COLORS.muted, anchor: 'start' });
    const geluY = wUpY + WEIGHT_H / 2 + ROW_GAP * 0.75;
    drawBadge(gs, IMG_CX, geluY, 'GELU', COLORS.ffn.fill, COLORS.ffn.stroke);
    arrowV(gs, IMG_CX, wUpY + WEIGHT_H / 2, geluY - 17, COLORS.ffn.stroke);
    const wDownY = geluY + 17 + ROW_GAP * 0.75 + WEIGHT_H / 2;
    drawWeightMat(gs, IMG_CX, wDownY, 'W_down', `[${dFf}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 120, WEIGHT_H);
    arrowV(gs, IMG_CX, geluY + 17, wDownY - WEIGHT_H / 2, COLORS.ffn.stroke);
    lbl(gs, IMG_CX + 80, wDownY - 10, 'down-project', { size: 8, color: COLORS.muted, anchor: 'start' });
    const ffnOutY = wDownY + WEIGHT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowV(gs, IMG_CX, wDownY + WEIGHT_H / 2, ffnOutY - MAT_H / 2, COLORS.ffn.stroke);
    drawSeqMat(gs, IMG_CX, ffnOutY, 'img_features', `[${nPatches}, ${dModel}]`, COLORS.ffn.fill, COLORS.ffn.stroke);
    drawShapeEq(gs, IMG_CX, ffnOutY + MAT_H / 2 + 24, `W_down(GELU(W_up(LN(h)))) → [${nPatches}, ${dModel}]`, COLORS.ffn.stroke);
    steps.push(makeStep(imgStepId, 'FFN', 'ViT Feed-Forward', `FFN(LN(x))`, 'Two linear layers with GELU activation.', 'step-vffn', COLORS.ffn.stroke, COLORS.ffn.fill));
    imgStepId++; iy = ffnOutY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 7: Image Projection ──
  {
    const gs = startGroup(g, 'step-iproj', imgStepId);
    const h = stepHeader(gs, IMG_CX, iy, imgStepId, 'Image Projection', `f_i · W_i`, COLORS.proj.fill, COLORS.proj.stroke);
    arrowV(gs, IMG_CX, iy, h, COLORS.proj.stroke);
    const rowY = h + BOX_TO_ROW + 24;
    const vecW = 200; const vecH = 40;
    gs.append('rect').attr('x', IMG_CX - 70 - vecW / 2).attr('y', rowY - vecH / 2).attr('width', vecW).attr('height', vecH).attr('rx', 5).attr('fill', COLORS.ffn.fill).attr('stroke', COLORS.ffn.stroke).attr('stroke-width', 1);
    lbl(gs, IMG_CX - 70, rowY + 1, `img_feat [${dModel}]`, { size: 9, weight: '600', color: COLORS.ffn.stroke });
    opCircle(gs, IMG_CX + 40, rowY, '×', COLORS.proj.stroke);
    drawArrow(gs as Sel, IMG_CX - 70 + vecW / 2 + 4, rowY, IMG_CX + 40 - 20, rowY, { color: COLORS.proj.stroke });
    drawWeightMat(gs, IMG_CX + 140, rowY, 'W_i', `[${dModel}, ${dProj}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 60);
    drawArrow(gs as Sel, IMG_CX + 40 + 20, rowY, IMG_CX + 140 - 50 - 4, rowY, { color: COLORS.proj.stroke });
    const outY = rowY + vecH / 2 + ROW_GAP + 20;
    arrowV(gs, IMG_CX + 40, rowY + vecH / 2, outY - 20, COLORS.proj.stroke);
    const outW = 200; const outH = 40;
    gs.append('rect').attr('x', IMG_CX - outW / 2).attr('y', outY - outH / 2).attr('width', outW).attr('height', outH).attr('rx', 6).attr('fill', COLORS.proj.fill).attr('stroke', COLORS.proj.stroke).attr('stroke-width', 1.5);
    lbl(gs, IMG_CX, outY + 1, `proj_img [${dProj}]`, { size: 9, weight: '600', color: COLORS.proj.stroke });
    drawShapeEq(gs, IMG_CX, outY + outH / 2 + 20, `img_features · W_i → [${dProj}]`, COLORS.proj.stroke);
    steps.push(makeStep(imgStepId, 'Proj_i', 'Image Projection', `f_i · W_i`, 'Project to shared embedding space.', 'step-iproj', COLORS.proj.stroke, COLORS.proj.fill));
    iy = outY + outH / 2 + 20 + STEP_GAP;
  }

  const imgBottom = iy;

  // ═══════════════════════════════════════════════════════════════════════
  // TEXT BRANCH (right)
  // ═══════════════════════════════════════════════════════════════════════
  let txtStepId = 7;
  let ty = y;

  // ── Step 7: Input Text ──
  {
    const gs = startGroup(g, 'step-text', txtStepId);
    const h = stepHeader(gs, TXT_CX, ty, txtStepId, 'Input Text', `tokens: [${seqLen}]`, COLORS.text.fill, COLORS.text.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.text.stroke);
    const stripY = h + BOX_TO_ROW + 28;
    drawTokenStrip(gs, TXT_CX, stripY, Math.min(seqLen, 12), COLORS.text.stroke, 300, 52);
    lbl(gs, TXT_CX, stripY - 36, `"a photo of a cat"`, { size: 9, color: COLORS.muted });
    lbl(gs, TXT_CX, stripY + 36, `${seqLen} tokens (BPE)`, { size: 8.5, color: COLORS.muted });
    const outY = stripY + 26 + ROW_GAP + MAT_H / 2;
    arrowV(gs, TXT_CX, stripY + 26 + 18, outY - MAT_H / 2, COLORS.text.stroke);
    drawSeqMat(gs, TXT_CX, outY, 'token_ids', `[${seqLen}]`, COLORS.text.fill, COLORS.text.stroke, SEQ_W, MAT_H - 12);
    steps.push(makeStep(txtStepId, 'Text', 'Input Text', `[${seqLen}]`, `Tokenized text (${seqLen} BPE tokens).`, 'step-text', COLORS.text.stroke, COLORS.text.fill));
    txtStepId++; ty = outY + MAT_H / 2 + STEP_GAP;
  }

  // ── Step 8: Token Embedding ──
  {
    const gs = startGroup(g, 'step-tok', txtStepId);
    const h = stepHeader(gs, TXT_CX, ty, txtStepId, 'Token Embedding', `E(tok)`, COLORS.tok.fill, COLORS.tok.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.tok.stroke);
    const rowY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, TXT_CX - 60, rowY, 'token_ids', `[${seqLen}]`, COLORS.text.fill, COLORS.text.stroke, 130, MAT_H - 12);
    opCircle(gs, TXT_CX + 40, rowY, '→', COLORS.tok.stroke);
    drawArrow(gs as Sel, TXT_CX - 60 + 65 + 4, rowY, TXT_CX + 40 - 20, rowY, { color: COLORS.tok.stroke });
    drawWeightMat(gs, TXT_CX + 140, rowY, 'E', `[${seqLen}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 110, 64);
    drawArrow(gs as Sel, TXT_CX + 40 + 20, rowY, TXT_CX + 140 - 55 - 4, rowY, { color: COLORS.tok.stroke });
    const outY = rowY + MAT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowV(gs, TXT_CX + 40, rowY + MAT_H / 2, outY - MAT_H / 2, COLORS.tok.stroke);
    drawSeqMat(gs, TXT_CX, outY, 'E(tok)', `[${seqLen}, ${dModel}]`, COLORS.tok.fill, COLORS.tok.stroke);
    drawShapeEq(gs, TXT_CX, outY + MAT_H / 2 + 24, `token_ids → E(tok) [${seqLen}, ${dModel}]`, COLORS.tok.stroke);
    steps.push(makeStep(txtStepId, 'TokEmb', 'Token Embedding', `E(tok)`, 'Lookup token embeddings.', 'step-tok', COLORS.tok.stroke, COLORS.tok.fill));
    txtStepId++; ty = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 9: Position Embedding ──
  {
    const gs = startGroup(g, 'step-tpos', txtStepId);
    const h = stepHeader(gs, TXT_CX, ty, txtStepId, 'Add Position Embedding', `E(tok) + PE`, COLORS.pos.fill, COLORS.pos.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.pos.stroke);
    const rowY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, TXT_CX - 80, rowY, 'E(tok)', `[${seqLen}, ${dModel}]`, COLORS.tok.fill, COLORS.tok.stroke, 150, MAT_H);
    opCircle(gs, TXT_CX + 30, rowY, '+', COLORS.pos.stroke);
    drawArrow(gs as Sel, TXT_CX - 80 + 75 + 4, rowY, TXT_CX + 30 - 20, rowY, { color: COLORS.pos.stroke });
    drawPosEncoding(gs, TXT_CX + 140, rowY, seqLen, COLORS.pos.stroke, 130, 56);
    lbl(gs, TXT_CX + 140, rowY - 28 - 10, 'learned PE', { size: 8, color: COLORS.muted });
    drawArrow(gs as Sel, TXT_CX + 140 - 65 - 4, rowY, TXT_CX + 30 + 20, rowY, { color: COLORS.pos.stroke });
    const outY = rowY + MAT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowV(gs, TXT_CX + 30, rowY + MAT_H / 2, outY - MAT_H / 2, COLORS.pos.stroke);
    drawSeqMat(gs, TXT_CX, outY, 'tokens', `[${seqLen}, ${dModel}]`, COLORS.pos.fill, COLORS.pos.stroke);
    drawShapeEq(gs, TXT_CX, outY + MAT_H / 2 + 24, `E(tok) + PE → [${seqLen}, ${dModel}]`, COLORS.pos.stroke);
    steps.push(makeStep(txtStepId, 'PosEnc', 'Add Position Embedding', `E(tok) + PE`, 'Add learned positional embeddings.', 'step-tpos', COLORS.pos.stroke, COLORS.pos.fill));
    txtStepId++; ty = outY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 10: Text Self-Attention ──
  {
    const gs = startGroup(g, 'step-tattn', txtStepId);
    const h = stepHeader(gs, TXT_CX, ty, txtStepId, 'Text Self-Attention', `Attn(LN(x))`, COLORS.attn.fill, COLORS.attn.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.attn.stroke);
    const inY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, TXT_CX, inY, 'tokens', `[${seqLen}, ${dModel}]`, COLORS.pos.fill, COLORS.pos.stroke);
    const lnY = inY + MAT_H / 2 + ROW_GAP;
    drawBadge(gs, TXT_CX, lnY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    arrowV(gs, TXT_CX, inY + MAT_H / 2, lnY - 17, COLORS.attn.stroke);
    const qkvY = lnY + 17 + ROW_GAP + 32;
    const qkvGap = 120;
    lbl(gs, TXT_CX - qkvGap, qkvY - 50, 'Q', { size: 9, weight: '600', color: COLORS.attn.stroke });
    lbl(gs, TXT_CX, qkvY - 50, 'K', { size: 9, weight: '600', color: COLORS.attn.stroke });
    lbl(gs, TXT_CX + qkvGap, qkvY - 50, 'V', { size: 9, weight: '600', color: COLORS.attn.stroke });
    drawWeightMat(gs, TXT_CX - qkvGap, qkvY, 'W_q', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 64);
    drawWeightMat(gs, TXT_CX, qkvY, 'W_k', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 64);
    drawWeightMat(gs, TXT_CX + qkvGap, qkvY, 'W_v', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 64);
    drawArrow(gs as Sel, TXT_CX, lnY + 17, TXT_CX - qkvGap, qkvY - 32 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, TXT_CX, lnY + 17, TXT_CX, qkvY - 32 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, TXT_CX, lnY + 17, TXT_CX + qkvGap, qkvY - 32 - 4, { color: COLORS.attn.stroke });
    const scoreY = qkvY + 32 + ROW_GAP;
    const scoreBoxW = 180; const scoreBoxH = 38;
    gs.append('rect').attr('x', TXT_CX - 60 - scoreBoxW / 2).attr('y', scoreY - scoreBoxH / 2).attr('width', scoreBoxW).attr('height', scoreBoxH).attr('rx', 6).attr('fill', '#fff').attr('stroke', COLORS.attn.stroke).attr('stroke-width', 1);
    lbl(gs, TXT_CX - 60, scoreY, `Q·K^T/√d`, { size: 9, weight: '600', color: COLORS.attn.stroke, font: 'monospace' });
    drawBadge(gs, TXT_CX + 80, scoreY, 'Softmax', COLORS.attn.fill, COLORS.attn.stroke);
    drawArrow(gs as Sel, TXT_CX - 60 + scoreBoxW / 2 + 4, scoreY, TXT_CX + 80 - 50, scoreY, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, TXT_CX - qkvGap, qkvY + 32, TXT_CX - 60 - 30, scoreY - scoreBoxH / 2 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, TXT_CX, qkvY + 32, TXT_CX - 60 + 30, scoreY - scoreBoxH / 2 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, TXT_CX + qkvGap, qkvY + 32, TXT_CX + 80, scoreY + scoreBoxH / 2 + 4, { color: COLORS.attn.stroke });
    const outY = scoreY + scoreBoxH / 2 + ROW_GAP + 30;
    drawWeightMat(gs, TXT_CX, outY, 'W_o', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 60);
    lbl(gs, TXT_CX, outY - 32 - 14, 'attn_weights · V', { size: 8, color: COLORS.muted });
    arrowV(gs, TXT_CX + 80, scoreY + scoreBoxH / 2 + 4, outY - 30, COLORS.attn.stroke);
    const attnOutY = outY + 30 + ROW_GAP + MAT_H / 2;
    arrowV(gs, TXT_CX, outY + 30, attnOutY - MAT_H / 2, COLORS.attn.stroke);
    drawSeqMat(gs, TXT_CX, attnOutY, 'attn_out', `[${seqLen}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke);
    drawShapeEq(gs, TXT_CX, attnOutY + MAT_H / 2 + 24, `softmax(Q·K^T/√d)·V·W_o → [${seqLen}, ${dModel}]`, COLORS.attn.stroke);
    steps.push(makeStep(txtStepId, 'Attn', 'Text Self-Attention', `Attn(LN(x))`, 'Multi-head self-attention with Q/K/V.', 'step-tattn', COLORS.attn.stroke, COLORS.attn.fill));
    txtStepId++; ty = attnOutY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 11: Text FFN ──
  {
    const gs = startGroup(g, 'step-tffn', txtStepId);
    const h = stepHeader(gs, TXT_CX, ty, txtStepId, 'Text Feed-Forward', `FFN(LN(x)) + residual`, COLORS.ffn.fill, COLORS.ffn.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.ffn.stroke);
    const inY = h + BOX_TO_ROW + MAT_H / 2;
    drawSeqMat(gs, TXT_CX, inY, 'h_attn', `[${seqLen}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke);
    const lnY = inY + MAT_H / 2 + ROW_GAP;
    drawBadge(gs, TXT_CX, lnY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    arrowV(gs, TXT_CX, inY + MAT_H / 2, lnY - 17, COLORS.ffn.stroke);
    const dFf = 4 * dModel;
    const wUpY = lnY + 17 + ROW_GAP + WEIGHT_H / 2;
    drawWeightMat(gs, TXT_CX, wUpY, 'W_up', `[${dModel}, ${dFf}]`, COLORS.weight.fill, COLORS.weight.stroke, 120, WEIGHT_H);
    arrowV(gs, TXT_CX, lnY + 17, wUpY - WEIGHT_H / 2, COLORS.ffn.stroke);
    lbl(gs, TXT_CX + 80, wUpY - 10, 'up-project', { size: 8, color: COLORS.muted, anchor: 'start' });
    const geluY = wUpY + WEIGHT_H / 2 + ROW_GAP * 0.75;
    drawBadge(gs, TXT_CX, geluY, 'GELU', COLORS.ffn.fill, COLORS.ffn.stroke);
    arrowV(gs, TXT_CX, wUpY + WEIGHT_H / 2, geluY - 17, COLORS.ffn.stroke);
    const wDownY = geluY + 17 + ROW_GAP * 0.75 + WEIGHT_H / 2;
    drawWeightMat(gs, TXT_CX, wDownY, 'W_down', `[${dFf}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 120, WEIGHT_H);
    arrowV(gs, TXT_CX, geluY + 17, wDownY - WEIGHT_H / 2, COLORS.ffn.stroke);
    lbl(gs, TXT_CX + 80, wDownY - 10, 'down-project', { size: 8, color: COLORS.muted, anchor: 'start' });
    const ffnOutY = wDownY + WEIGHT_H / 2 + ROW_GAP + MAT_H / 2;
    arrowV(gs, TXT_CX, wDownY + WEIGHT_H / 2, ffnOutY - MAT_H / 2, COLORS.ffn.stroke);
    drawSeqMat(gs, TXT_CX, ffnOutY, 'txt_features', `[${seqLen}, ${dModel}]`, COLORS.ffn.fill, COLORS.ffn.stroke);
    drawShapeEq(gs, TXT_CX, ffnOutY + MAT_H / 2 + 24, `W_down(GELU(W_up(LN(h)))) → [${seqLen}, ${dModel}]`, COLORS.ffn.stroke);
    steps.push(makeStep(txtStepId, 'FFN', 'Text Feed-Forward', `FFN(LN(x))`, 'Two linear layers with GELU activation.', 'step-tffn', COLORS.ffn.stroke, COLORS.ffn.fill));
    txtStepId++; ty = ffnOutY + MAT_H / 2 + 24 + STEP_GAP;
  }

  // ── Step 12: Text Projection ──
  {
    const gs = startGroup(g, 'step-tproj', txtStepId);
    const h = stepHeader(gs, TXT_CX, ty, txtStepId, 'Text Projection', `f_t · W_t`, COLORS.proj.fill, COLORS.proj.stroke);
    arrowV(gs, TXT_CX, ty, h, COLORS.proj.stroke);
    const rowY = h + BOX_TO_ROW + 24;
    const vecW = 200; const vecH = 40;
    gs.append('rect').attr('x', TXT_CX - 70 - vecW / 2).attr('y', rowY - vecH / 2).attr('width', vecW).attr('height', vecH).attr('rx', 5).attr('fill', COLORS.ffn.fill).attr('stroke', COLORS.ffn.stroke).attr('stroke-width', 1);
    lbl(gs, TXT_CX - 70, rowY + 1, `txt_feat [${dModel}]`, { size: 9, weight: '600', color: COLORS.ffn.stroke });
    opCircle(gs, TXT_CX + 40, rowY, '×', COLORS.proj.stroke);
    drawArrow(gs as Sel, TXT_CX - 70 + vecW / 2 + 4, rowY, TXT_CX + 40 - 20, rowY, { color: COLORS.proj.stroke });
    drawWeightMat(gs, TXT_CX + 140, rowY, 'W_t', `[${dModel}, ${dProj}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 60);
    drawArrow(gs as Sel, TXT_CX + 40 + 20, rowY, TXT_CX + 140 - 50 - 4, rowY, { color: COLORS.proj.stroke });
    const outY = rowY + vecH / 2 + ROW_GAP + 20;
    arrowV(gs, TXT_CX + 40, rowY + vecH / 2, outY - 20, COLORS.proj.stroke);
    const outW = 200; const outH = 40;
    gs.append('rect').attr('x', TXT_CX - outW / 2).attr('y', outY - outH / 2).attr('width', outW).attr('height', outH).attr('rx', 6).attr('fill', COLORS.proj.fill).attr('stroke', COLORS.proj.stroke).attr('stroke-width', 1.5);
    lbl(gs, TXT_CX, outY + 1, `proj_txt [${dProj}]`, { size: 9, weight: '600', color: COLORS.proj.stroke });
    drawShapeEq(gs, TXT_CX, outY + outH / 2 + 20, `txt_features · W_t → [${dProj}]`, COLORS.proj.stroke);
    steps.push(makeStep(txtStepId, 'Proj_t', 'Text Projection', `f_t · W_t`, 'Project to shared embedding space.', 'step-tproj', COLORS.proj.stroke, COLORS.proj.fill));
    ty = outY + outH / 2 + 20 + STEP_GAP;
  }

  const txtBottom = ty;

  // ═══════════════════════════════════════════════════════════════════════
  // CONTRASTIVE SECTION (center)
  // ═══════════════════════════════════════════════════════════════════════
  let cStepId = 13;
  y = Math.max(imgBottom, txtBottom);

  // ── Step 13: L2 Normalize ──
  {
    const gs = startGroup(g, 'step-norm', cStepId);
    const h = stepHeader(gs, CX, y, cStepId, 'L2 Normalize', `f̂ = f / ‖f‖₂`, COLORS.norm.fill, COLORS.norm.stroke, CENTER_W);
    const barY = h - 50;
    gs.append('line').attr('x1', IMG_CX).attr('y1', barY).attr('x2', TXT_CX).attr('y2', barY).attr('stroke', COLORS.norm.stroke).attr('stroke-width', 1.5);
    drawArrow(gs as Sel, IMG_CX, imgBottom - STEP_GAP + 48, IMG_CX, barY, { color: COLORS.norm.stroke });
    drawArrow(gs as Sel, TXT_CX, txtBottom - STEP_GAP + 48, TXT_CX, barY, { color: COLORS.norm.stroke });
    drawArrow(gs as Sel, CX, barY, CX, h, { color: COLORS.norm.stroke });
    const rowY = h + BOX_TO_ROW + 20;
    const normW = 200; const normH = 40;
    gs.append('rect').attr('x', IMG_CX - normW / 2).attr('y', rowY - normH / 2).attr('width', normW).attr('height', normH).attr('rx', 6).attr('fill', COLORS.norm.fill).attr('stroke', COLORS.norm.stroke).attr('stroke-width', 1.5);
    lbl(gs, IMG_CX, rowY + 1, `f̂_img [${dProj}]`, { size: 9, weight: '600', color: COLORS.norm.stroke });
    gs.append('rect').attr('x', TXT_CX - normW / 2).attr('y', rowY - normH / 2).attr('width', normW).attr('height', normH).attr('rx', 6).attr('fill', COLORS.norm.fill).attr('stroke', COLORS.norm.stroke).attr('stroke-width', 1.5);
    lbl(gs, TXT_CX, rowY + 1, `f̂_txt [${dProj}]`, { size: 9, weight: '600', color: COLORS.norm.stroke });
    drawShapeEq(gs, CX, rowY + normH / 2 + 20, `f̂ = f / ‖f‖₂  (unit sphere)`, COLORS.norm.stroke);
    steps.push(makeStep(cStepId, 'Norm', 'L2 Normalize', `f̂ = f / ‖f‖₂`, 'Normalize to unit norm for cosine similarity.', 'step-norm', COLORS.norm.stroke, COLORS.norm.fill));
    cStepId++; y = rowY + normH / 2 + 20 + STEP_GAP;
  }

  const normRowBottom = y;

  // ── Step 14: Cosine Similarity ──
  {
    const gs = startGroup(g, 'step-sim', cStepId);
    const h = stepHeader(gs, CX, y, cStepId, 'Cosine Similarity', `sim = f̂_img · f̂_txt`, COLORS.sim.fill, COLORS.sim.stroke, CENTER_W);
    arrowV(gs, IMG_CX + 60, normRowBottom - STEP_GAP + 40, h + BOX_H, COLORS.norm.stroke);
    arrowV(gs, TXT_CX - 60, normRowBottom - STEP_GAP + 40, h + BOX_H, COLORS.norm.stroke);
    const simY = h + BOX_TO_ROW + 20;
    const simW = 320; const simH = 44;
    gs.append('rect').attr('x', CX - simW / 2).attr('y', simY - simH / 2).attr('width', simW).attr('height', simH).attr('rx', 8).attr('fill', COLORS.sim.fill).attr('stroke', COLORS.sim.stroke).attr('stroke-width', 2);
    lbl(gs, CX, simY + 1, `cos_sim = f̂_imgᵀ · f̂_txt ∈ [-1, 1]`, { size: 9.5, weight: '600', color: COLORS.sim.stroke, font: 'monospace' });
    steps.push(makeStep(cStepId, 'Sim', 'Cosine Similarity', `sim = f̂_img · f̂_txt`, 'Dot product of normalized features.', 'step-sim', COLORS.sim.stroke, COLORS.sim.fill));
    cStepId++; y = simY + simH / 2 + ROW_GAP;
  }

  // ── Step 15: Contrastive Loss ──
  {
    const gs = startGroup(g, 'step-loss', cStepId);
    const h = stepHeader(gs, CX, y, cStepId, 'Contrastive Loss', `L = -log(exp(sim/τ) / Σexp)`, COLORS.loss.fill, COLORS.loss.stroke, CENTER_W);
    arrowV(gs, CX, y, h, COLORS.loss.stroke);
    const rowY = h + BOX_TO_ROW + 28;
    const tauW = 160; const tauH = 40;
    gs.append('rect').attr('x', CX - 180 - tauW / 2).attr('y', rowY - tauH / 2).attr('width', tauW).attr('height', tauH).attr('rx', 6).attr('fill', '#fff').attr('stroke', COLORS.loss.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX - 180, rowY + 1, `τ = learnable`, { size: 9, weight: '600', color: COLORS.loss.stroke });
    lbl(gs, CX - 180, rowY + 18, 'temperature', { size: 7.5, color: COLORS.muted });
    const logitW = 220;
    gs.append('rect').attr('x', CX + 100 - logitW / 2).attr('y', rowY - tauH / 2).attr('width', logitW).attr('height', tauH).attr('rx', 6).attr('fill', COLORS.loss.fill).attr('stroke', COLORS.loss.stroke).attr('stroke-width', 1);
    lbl(gs, CX + 100, rowY + 1, `logits = sim / τ`, { size: 9, weight: '600', color: COLORS.loss.stroke, font: 'monospace' });
    drawArrow(gs as Sel, CX - 180 + tauW / 2 + 4, rowY, CX + 100 - logitW / 2 - 4, rowY, { color: COLORS.loss.stroke });
    const lossY = rowY + tauH / 2 + ROW_GAP + 28;
    const lossW = 520; const lossH = 64;
    gs.append('rect').attr('x', CX - lossW / 2).attr('y', lossY - lossH / 2).attr('width', lossW).attr('height', lossH).attr('rx', 8).attr('fill', COLORS.loss.fill).attr('stroke', COLORS.loss.stroke).attr('stroke-width', 1.5);
    arrowV(gs, CX + 100, rowY + tauH / 2, lossY - lossH / 2, COLORS.loss.stroke);
    lbl(gs, CX, lossY - 10, 'InfoNCE Loss (symmetric cross-entropy)', { size: 10, weight: '700', color: COLORS.loss.stroke });
    lbl(gs, CX, lossY + 8, `L = ½(L_i2t + L_t2i)   over batch of N pairs`, { size: 8.5, color: COLORS.loss.stroke, font: 'monospace' });
    lbl(gs, CX, lossY + 24, `pull matching pairs, push mismatched`, { size: 8, color: COLORS.muted });
    steps.push(makeStep(cStepId, 'Loss', 'Contrastive Loss', `InfoNCE`, 'Symmetric cross-entropy over similarity.', 'step-loss', COLORS.loss.stroke, COLORS.loss.fill));
    y = lossY + lossH / 2 + STEP_GAP;
  }

  // ── Output ──
  {
    const gs = startGroup(g, 'step-out', cStepId);
    const outW = 560; const outH = 46;
    gs.append('rect').attr('x', CX - outW / 2).attr('y', y).attr('width', outW).attr('height', outH).attr('rx', 6).attr('fill', COLORS.out.fill).attr('stroke', COLORS.out.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX, y + outH / 2 + 1, `Aligned image-text embeddings · d_proj = ${dProj}`, { size: 10, weight: '600', color: COLORS.out.stroke });
    steps.push(makeStep(cStepId, 'Output', 'Aligned Embeddings', `d_proj=${dProj}`, 'Learned aligned image-text embedding space.', 'step-out', COLORS.out.stroke, COLORS.out.fill));
    y += outH + 48;
  }

  return { steps, y };
}

export function renderClipEncoderDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const nPatches = Number(params.n_patches) || 196;
  const seqLen = Number(params.seq_len) || 77;

  const root = g as unknown as Gsel;
  let y = 28;

  lbl(root, CX, y, 'CLIP Encoder', { size: 18, weight: '700', color: COLORS.textCol });
  y += 24;
  const gridN = Math.round(Math.sqrt(nPatches));
  lbl(root, CX, y, `Contrastive Language-Image Pre-training · d_model=${dModel} · ${gridN}×${gridN} patches · seq_len=${seqLen}`, { size: 10, color: COLORS.muted });
  y += 32;

  const patchDim = 16 * 16 * 3;
  const vitParams = patchDim * dModel + dModel * dModel * 4 + dModel * 4;
  const textParams = dModel * dModel * 4 + dModel * 4 + seqLen * dModel;
  const projParams = dModel * dModel * 2;
  y = drawParamSummary(root, CX, y, [`d_model=${dModel}`, `ViT≈${fmtNum(vitParams)}`, `Text≈${fmtNum(textParams)}`, `proj=${fmtNum(projParams)}`]);
  y += 20;

  const result = renderClipPipeline(root, y, dModel, nPatches, seqLen);

  let footerY = result.y + 24;

  const insightText = `CLIP trains dual encoders: a ViT processes ${gridN}×${gridN} patches (patch_size=16) into image features, while a transformer encodes ${seqLen}-token text. Both are projected to a shared d=${dModel} space, L2-normalized, and aligned via contrastive loss (InfoNCE with learned temperature τ). Matched image-text pairs are pulled together, mismatches pushed apart.`;
  const perfText = `ViT encoder: ~${fmtNum(vitParams)} params (patch embed + ${gridN}²×${dModel} attention/FFN). Text encoder: ~${fmtNum(textParams)} params. Projection heads: ${fmtNum(projParams)}. Total: ~${fmtNum(vitParams + textParams + projParams)} params.`;

  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 14;

  const codeLines = [
    '# CLIP Contrastive Learning',
    `img_features = vit_encoder(patchify(image))     # [B, ${dModel}]`,
    `txt_features = text_encoder(tokenize(text))      # [B, ${dModel}]`,
    `img_proj = img_features @ W_i                    # [B, ${dModel}]`,
    `txt_proj = txt_features @ W_t                    # [B, ${dModel}]`,
    'img_norm = F.normalize(img_proj, dim=-1)',
    'txt_norm = F.normalize(txt_proj, dim=-1)',
    'similarity = img_norm @ txt_norm.T               # [B, B]',
    `logits = similarity * exp(log_temp)               # τ learnable`,
    'loss = (CE(logits, labels) + CE(logits.T, labels)) / 2',
  ];

  footerY = drawCodeAnnotation(g, 80, footerY, W - 160, 'CLIP Encoder — Contrastive Image-Text', [], codeLines);

  return { width: W, height: footerY + 24, steps: result.steps };
}
